from pathlib import Path
from playwright.sync_api import sync_playwright
import json,base64
ROOT=Path(__file__).resolve().parents[2]
out=ROOT/'bestiary-audit';out.mkdir(exist_ok=True)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--allow-file-access-from-files','--no-sandbox'])
 page=b.new_page(viewport={'width':1100,'height':700});errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.goto((ROOT/'update/thebound.html').as_uri());page.wait_for_timeout(2200)
 page.click('#tNew');page.wait_for_timeout(400);page.fill('#ccName','Revisión visual');page.click('#ccGo');page.wait_for_timeout(1200);page.click('#introOk');page.wait_for_timeout(2000)
 result=page.evaluate("()=>{const entries=[...Object.entries(MOBS).map(([id,def])=>({id,def,boss:false})),...Object.entries(BOSSES).map(([id,def])=>({id:'B_'+id,def,boss:true}))],meta=[],images={};\nfor(const boss of [false,true]){const rows=entries.filter(e=>e.boss===boss);for(let start=0;start<rows.length;start+=20){const chunk=rows.slice(start,start+20),cv=mkCanvas(1120,80+Math.ceil(chunk.length/4)*210),x=cv.getContext('2d');x.fillStyle='#202b3b';x.fillRect(0,0,cv.width,cv.height);x.font='bold 21px sans-serif';x.fillStyle='#fff0d3';x.fillText('THE BOUND 4.98 · '+(boss?'JEFES':'ENEMIGOS')+' · '+(start+1)+'–'+(start+chunk.length),20,28);x.font='12px sans-serif';x.fillStyle='#becfe0';x.fillText('Arriba: frente / perfil / espalda con el dibujado del juego. Abajo: icono del bestiario / ataque.',20,51);\nchunk.forEach((e,k)=>{const ox=(k%4)*280,oy=80+Math.floor(k/4)*210,D=e.def;const m={id:e.id,name:D.n,boss,art:D.art,lv:D.lv,reg:D.reg||[],where:D.where||'',error:null};meta.push(m);x.fillStyle='#fff0d3';x.font='bold 13px sans-serif';x.fillText(e.id+' · '+D.n,ox+5,oy,270);x.font='11px sans-serif';x.fillStyle='#a8bfd5';x.fillText(JSON.stringify(D.art).slice(0,75),ox+5,oy+17,270);\ntry{const A=mobAtlasFor(D.art);if(!A||!A.img)throw Error('No atlas');m.size=[A.fw,A.fh];m.hi=!!(A.hi||A.hdL);m.rows=A.img.height/A.fh;m.cols=A.img.width/A.fw;const hashes=[];\nfunction tile(col,row,xx,yy,w,h,raw){const c=mkCanvas(96,96),g=c.getContext('2d');g.imageSmoothingEnabled=false;const s=Math.min(96/A.fw,96/A.fh),ww=A.fw*s,hh=A.fh*s;if(raw)g.drawImage(A.img,col*A.fw,row*A.fh,A.fw,A.fh,(96-ww)/2,96-hh,ww,hh);else atlasBlit(g,A,col,row,(96-ww)/2,96-hh,ww,hh);x.imageSmoothingEnabled=false;x.drawImage(c,xx,yy,w,h);let hash=2166136261;for(const b of g.getImageData(0,0,96,96).data)hash=Math.imul(hash^b,16777619)>>>0;return hash;}\nfor(const [i,row]of [0,1,3].entries())hashes.push(tile(A.idx.idle||0,row,ox+i*90,oy+25,90,90,false));\nm.viewHashes=hashes;m.bestHash=tile(A.idx.idle||0,0,ox+22,oy+122,70,70,true);m.attackHash=tile(A.idx.atk??A.idx.idle??0,0,ox+128,oy+122,70,70,false);\n}catch(err){m.error=String(err);x.fillStyle='#ff6666';x.fillText(m.error,ox+5,oy+75,270);}});images[(boss?'jefes':'enemigos')+'_'+String(start/20+1).padStart(2,'0')+'.png']=cv.toDataURL('image/png');}}\nreturn {meta,images,totals:{mobs:Object.keys(MOBS).length,bosses:Object.keys(BOSSES).length}};}")
 for name,data in result.pop('images').items():(out/name).write_bytes(base64.b64decode(data.split(',')[1]))
 result['pageErrors']=errors;(out/'catalogo.json').write_text(json.dumps(result,ensure_ascii=False,indent=2));print(json.dumps({'totals':result['totals'],'errors':errors,'missing':[m['id'] for m in result['meta'] if m['error']]}))
 page.evaluate("()=>{for(const id in MOBS)G.P.best[id]=1;for(const id in BOSSES)G.P.best['B_'+id]=1;closeModal();openPanel('best');}")
 page.wait_for_timeout(800);page.screenshot(path=str(out/'bestiario_interfaz.png'));b.close()
